ValidationRule.errorConditionFormula:
AND(
    ISCHANGED(Status),
    NOT(
        AND(
            LOWER(TEXT(PRIORVALUE(Status))) = "new",
            LOWER(TEXT(Status)) = "pending approval"
        )
    ),
    NOT(
        AND(
            LOWER(TEXT(PRIORVALUE(Status))) = "pending approval",
            LOWER(TEXT(Status)) = "approved"
        )
    ),
    NOT(
        AND(
            LOWER(TEXT(PRIORVALUE(Status))) = "pending approval",
            LOWER(TEXT(Status)) = "new"
        )
    ),
    NOT(
        AND(
            LOWER(TEXT(PRIORVALUE(Status))) = "approved",
            OR(
                LOWER(TEXT(Status)) = "integrated",
                LOWER(TEXT(Status)) = "integration error"
            )
        )
    ),
    NOT(
        AND(
            LOWER(TEXT(PRIORVALUE(Status))) = "integration error",
            OR(
                LOWER(TEXT(Status)) = "integrated",
                LOWER(TEXT(Status)) = "integration error"
            )
        )
    ),
    NOT(
        AND(
            LOWER(TEXT(PRIORVALUE(Status))) = "integration error",
            LOWER(TEXT(Status)) = "new"
        )
    )
)
